import{at as e,it as t,t as n,vt as r}from"./chunks/framework.B8IeflXD.js";var i=JSON.parse(`{"title":"The seat table","description":"","frontmatter":{},"headers":[],"relativePath":"why-seats.md","filePath":"pages/why-seats.md"}`),a={name:`why-seats.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="the-seat-table" tabindex="-1">The seat table <a class="header-anchor" href="#the-seat-table" aria-label="Permalink to “The seat table”">​</a></h1><p>Which axis scrolls is a state key, and no stage in the kernel branches on it. Two lookup tables carry the whole transpose.</p><h2 id="the-boundary" tabindex="-1">The boundary <a class="header-anchor" href="#the-boundary" aria-label="Permalink to “The boundary”">​</a></h2><p>Past <code>src/12_transpose.ts</code> the kernel speaks of a vertical seat and a horizontal seat and never asks which one holds a row.</p><div class="language-ts"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">g.state.orientation.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;columns&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">g.view.vertical.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()      </span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">// whichever axis now scrolls, pages, and pins</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">g.view.horizontal.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()    </span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">// the other one</span></span></code></pre></div><h2 id="the-receipt" tabindex="-1">The receipt <a class="header-anchor" href="#the-receipt" aria-label="Permalink to “The receipt”">​</a></h2><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rnE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;if *\\(.*orientation|orientation *===|orientation *!==&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/</span></span></code></pre></div><p>That prints nothing and exits non-zero, tests included. Every read of the key is an index into a table rather than a branch, and there are four of them in the grid constructor.</p><table tabindex="0"><thead><tr><th>table in <code>src/12_transpose.ts</code></th><th>what it holds</th></tr></thead><tbody><tr><td><code>SEATS</code></td><td>one row per orientation, mapping it to a seat pair</td></tr><tr><td><code>FLIPPED</code></td><td>the seat pair the other way round</td></tr></tbody></table><p><code>transpose</code> in <code>src/12_transpose.ts</code> is its own inverse, which is what a round trip rests on, and <code>src/12_transpose.test.ts</code> asserts that transposing twice returns the original plan.</p><p>A third orientation would be a third row in the table and no other edit anywhere.</p><h2 id="why-a-branch-would-have-been-the-wrong-shape" tabindex="-1">Why a branch would have been the wrong shape <a class="header-anchor" href="#why-a-branch-would-have-been-the-wrong-shape" aria-label="Permalink to “Why a branch would have been the wrong shape”">​</a></h2><p>Every stage that reads a row would need a column twin, so the branch that section one greps for would appear once per stage rather than once. The seat pair moves that decision to the boundary and leaves every stage below it monomorphic.</p><p>Spanning is the sharpest case. A span declared as two rows by three columns has to become three rows by two columns after a flip, so a declaration in the reader&#39;s vocabulary cannot be what any stage reads. <code>neutralSpan</code> in <code>src/12_transpose.ts</code> crosses it once, and the covered set swaps with it. See <a href="/hafley-rxjs/signal-grid/cells-span">Span</a>.</p><h2 id="what-is-finished-and-what-is-not" tabindex="-1">What is finished, and what is not <a class="header-anchor" href="#what-is-finished-and-what-is-not" aria-label="Permalink to “What is finished, and what is not”">​</a></h2><table tabindex="0"><thead><tr><th>half</th><th>state</th></tr></thead><tbody><tr><td>the model</td><td>asserted, including spans, the round trip, and list view</td></tr><tr><td>the renderer</td><td>a transposed grid builds its frame and writes no cell values</td></tr></tbody></table><p>A cell reads its value out of the row axis&#39;s own map, and under a transposed orientation the vertical key is a column id, which owns no row value. Writing the key after a render moves the header band and leaves the plan on the previous axis, which is the renderer&#39;s subscription rather than the derivation: the same write with no renderer attached moves the plan correctly.</p><p><code>demo/3_matrix.ts</code> carries the workaround, rewriting the transposed header band after each pass. The route is on <a href="/hafley-rxjs/signal-grid/showcase-matrix">Matrix</a>.</p><h2 id="list-view-is-the-same-lever" tabindex="-1">List view is the same lever <a class="header-anchor" href="#list-view-is-the-same-lever" aria-label="Permalink to “List view is the same lever”">​</a></h2><p><code>collapseToOneEntry</code> in <code>src/12_transpose.ts</code> keeps one entry on the horizontal axis, so every vertical entry renders as a single cell. A list is a degenerate transpose rather than a second rendering mode, which is why selection, pinning, and virtualization all keep working inside one.</p>`,20)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};